INSERT INTO "products" ("id","slug","name","description","original_price","pum","net_content","net_weight_g","stock","sku","cost_cop","images_json","source_data_json","barcode","invima","brand","laboratory","line","video_url","badges_json","active","sort_order","seo_title","seo_description","minimum_order_quantity","created_at","updated_at") VALUES('jm-040','jm-vitamina-c','Vitamina C','<h1><span style="color: #2b8a3e;">Vitamina</span> <span style="color: #c92a2a;">C</span></h1> <b><span style="color: #d9480f;">Refuerza el sistema inmunológico</span></b><br> &nbsp;<br> <dl>     <dt>         CAPSULA 500 mg.<br><span style="font-weight: 400;">100 Capsulas</span>     </dt> </dl> <hr> <dl>     <dt>         MODO DE USO:<br><span style="font-weight: 400;">Tomar 3 cápsulas diarias: una cápsula 30 minutos antes de cada comida principal (desayuno, almuerzo y cena).</span>     </dt> </dl> <dl>     <dt>         PRECAUCIONES:<br><span style="font-weight: 400;">Producto natural sin efectos secundarios conocidos. Se recomienda no exceder la dosis diaria sugerida.</span></dt></dl><hr> <dl>     <dt>         CONTENIDO:<br><span style="font-weight: 400;">Naranja, Kiwi, Arandano, Camu camu. 100% naturales. Harina tratada micropulverizada e irradiada.</span>     </dt> </dl> <dl>     <dt>RECOMENDACIONES:<br><span style="font-weight: 400;">Ayuda a reparar y mantener el cartílago, los huesos y los dientes, antioxidante, previene el Alzheimer, arterioesclerosis, cicatrizante, previene las enfermedades cardiacas ya que el ácido ascórbico disminuye el colesterol lo que evita que la grasa se adhiera a los vasos sanguineos, reduciendo la posibilidad de sufrir infartos. Sistema inmonologico. Resfrios, gripes, ayuda a la absorción de hierro, antioxidantes.</span>     </dt> </dl>',11000,NULL,NULL,NULL,12,'vitamina-c',9000,'"https://images.jumpseller.com/store/naturalmedix/34770421/flayer_vitamina_c.jpeg?1777778519"','{"Permalink":"vitamina-c","Name":"Vitamina C","Description":"<h1><span style=\"c