arios.                      CONTENIDO:-                     PROPIEDADES:-      ","Width":"6.5","Length":"6.5","Height":"11.0","Brand":"Natural medix","Barcode":"","Categories":"Natural medix,Natura Mix,Natural medix Cali,Natural medix Colombia,NaturalMedix,Cápsulas,Catálogo,Oficial,ORIGINAL,Productos Natural Medix","Images":"https://images.jumpseller.com/store/naturalmedix/35157950/colageno-hidrolizado-aguaje-maca-fenocreco.png?1777767377,https://images.jumpseller.com/store/naturalmedix/35157950/colageno-hidrolizado-aguaje-maca-fenocreco-a.png?1777767377,https://images.jumpseller.com/store/naturalmedix/35157950/natural-medix-marca.png?1777767377","Digital":"NO","Featured":"NO","Status":"not-available","SKU":"colageno-hidrolizado-aguaje-maca-fenogreco","Weight":"0.1","Cost per item":"9000.0","Compare at price":"","Stock":"0","Stock Unlimited":"NO","Stock Notification":"NO","Stock Threshold":"0","Price":"11000.0","Quotable":"NO","Minimum Quantity":"","Maximum Quantity":"","Google Product Category":""}',NULL,NULL,'Natural medix',NULL,NULL,NULL,'[{"bg":"badge-teal","icon":"https://fonts.gstatic.com/s/e/notoemoji/latest/2b50/512.webp","text":"Marca Natural medix"},{"bg":"badge-green","icon":"https://fonts.gstatic.com/s/e/notoemoji/latest/2705/512.webp","text":"Cápsulas"}]',0,80,'COLÁGENO HIDROLIZADO','     COLÁGENO HIDROLIZADO                   CAPSULA 500 mg.100 Capsulas                      MODO DE USO:Tomar 3 capsulas diarias, una cada media hora antes de las comidas.                     CONTRAINDICACIONES:No tiene contraindicaciones ni efectos secundarios.                      CONTENIDO:-                     PROPIEDADES:-      ',1,'2026-09-26 23:45:08','2026-09-26 23:45:08');
